<script lang="ts">
	import { toast } from 'svelte-sonner';
	import { config, models, settings } from '$lib/stores';
	import { getContext, onMount, tick } from 'svelte';
	import type { Writable } from 'svelte/store';
	import type { i18n as i18nType } from 'i18next';
	import {
		getPipelineValves,
		getPipelineValvesSpec,
		updatePipelineValves,
		getPipelines,
		getModels,
		getPipelinesList,
		downloadPipeline,
		deletePipeline,
		uploadPipeline
	} from '$lib/apis';

	import Spinner from '$lib/components/common/Spinner.svelte';
	import Switch from '$lib/components/common/Switch.svelte';
	import AdminSettingField from './AdminSettingField.svelte';
	import AdminSettingRow from './AdminSettingRow.svelte';
	import AdminSettingSection from './AdminSettingSection.svelte';
	import SettingsSelect from '$lib/components/common/SettingsSelect.svelte';

	const i18n: Writable<i18nType> = getContext('i18n');

	export let saveHandler: Function;

	let downloading = false;
	let uploading = false;

	let pipelineFiles: any = null;

	let PIPELINES_LIST: any[] | null = null;
	let selectedPipelinesUrlIdx = '';

	let pipelines: any[] | null = null;

	let valves: any = null;
	let valves_spec: any = null;
	let selectedPipelineIdx = 0;

	let pipelineDownloadUrl = '';
	const inputClass =
		'w-full h-7 rounded-lg border border-gray-100/50 bg-gray-50/40 px-2 text-xs text-gray-700 outline-hidden transition-colors placeholder:text-gray-300 focus:border-blue-400 dark:border-white/[0.04] dark:bg-white/[0.03] dark:text-gray-300 dark:placeholder:text-gray-700 dark:focus:border-blue-500';
	const actionButtonClass =
		'shrink-0 text-xs text-gray-500 transition-colors hover:text-gray-900 disabled:opacity-50 dark:text-gray-500 dark:hover:text-white';
	const mutedMessageClass = 'text-xs text-gray-400 dark:text-gray-600';

	const updateHandler = async () => {
		if (!pipelines) {
			toast.error($i18n.t('No valves to update'));
			return;
		}

		const pipeline = pipelines[selectedPipelineIdx];

		if (pipeline && (pipeline?.valves ?? false)) {
			for (const property in valves_spec.properties) {
				if (valves_spec.properties[property]?.type === 'array') {
					valves[property] = (valves[property] ?? '').split(',').map((v: string) => v.trim());
				}
			}

			const res = await updatePipelineValves(
				localStorage.token,
				pipeline.id,
				valves,
				selectedPipelinesUrlIdx
			).catch((error) => {
				toast.error(`${error}`);
			});

			if (res) {
				toast.success($i18n.t('Valves updated successfully'));
				setPipelines();
				models.set(
					await getModels(
						localStorage.token,
						$config?.features?.enable_direct_connections
							? ($settings?.directConnections ?? null)
							: null
					)
				);
				saveHandler();
			}
		} else {
			toast.error($i18n.t('No valves to update'));
		}
	};

	const getValves = async (idx: number) => {
		if (!pipelines?.[idx]) {
			return;
		}

		valves = null;
		valves_spec = null;

		valves_spec = await getPipelineValvesSpec(
			localStorage.token,
			pipelines[idx].id,
			selectedPipelinesUrlIdx
		);
		valves = await getPipelineValves(
			localStorage.token,
			pipelines[idx].id,
			selectedPipelinesUrlIdx
		);

		for (const property in valves_spec.properties) {
			if (valves_spec.properties[property]?.type === 'array') {
				valves[property] = valves[property].join(',');
			}
		}
	};

	const setPipelines = async () => {
		pipelines = null;
		valves = null;
		valves_spec = null;

		if ((PIPELINES_LIST ?? []).length > 0) {
			console.debug(selectedPipelinesUrlIdx);
			const loadedPipelines = await getPipelines(localStorage.token, selectedPipelinesUrlIdx);
			pipelines = loadedPipelines;

			if (loadedPipelines.length > 0) {
				selectedPipelineIdx = 0;
				await getValves(selectedPipelineIdx);
			}
		} else {
			pipelines = [];
		}
	};

	const addPipelineHandler = async () => {
		downloading = true;
		const res = await downloadPipeline(
			localStorage.token,
			pipelineDownloadUrl,
			selectedPipelinesUrlIdx
		).catch((error) => {
			toast.error(`${error}`);
			return null;
		});

		if (res) {
			toast.success($i18n.t('Pipeline downloaded successfully'));
			setPipelines();
			models.set(
				await getModels(
					localStorage.token,
					$config?.features?.enable_direct_connections
						? ($settings?.directConnections ?? null)
						: null
				)
			);
		}

		downloading = false;
	};

	const uploadPipelineHandler = async () => {
		uploading = true;

		if (pipelineFiles && pipelineFiles.length !== 0) {
			const file = pipelineFiles[0];

			console.log(file);

			const res = await uploadPipeline(localStorage.token, file, selectedPipelinesUrlIdx).catch(
				(error) => {
					console.error(error);
					toast.error($i18n.t('Something went wrong :/'));
					return null;
				}
			);

			if (res) {
				toast.success($i18n.t('Pipeline downloaded successfully'));
				setPipelines();
				models.set(
					await getModels(
						localStorage.token,
						$config?.features?.enable_direct_connections
							? ($settings?.directConnections ?? null)
							: null
					)
				);
			}
		} else {
			toast.error($i18n.t('No file selected'));
		}

		pipelineFiles = null;
		const pipelineUploadInputElement = document.getElementById(
			'pipelines-upload-input'
		) as HTMLInputElement | null;

		if (pipelineUploadInputElement) {
			pipelineUploadInputElement.value = '';
		}

		uploading = false;
	};

	const deletePipelineHandler = async () => {
		const pipeline = pipelines?.[selectedPipelineIdx];
		if (!pipeline) {
			return;
		}

		const res = await deletePipeline(
			localStorage.token,
			pipeline.id,
			selectedPipelinesUrlIdx
		).catch((error) => {
			toast.error(`${error}`);
			return null;
		});

		if (res) {
			toast.success($i18n.t('Pipeline deleted successfully'));
			setPipelines();
			models.set(
				await getModels(
					localStorage.token,
					$config?.features?.enable_direct_connections
						? ($settings?.directConnections ?? null)
						: null
				)
			);
		}
	};

	onMount(async () => {
		PIPELINES_LIST = await getPipelinesList(localStorage.token);
		console.log(PIPELINES_LIST);

		const pipelinesList = PIPELINES_LIST ?? [];
		if (pipelinesList.length > 0) {
			selectedPipelinesUrlIdx = pipelinesList[0]['idx'].toString();
		}

		await setPipelines();
	});
</script>

<form
	class="flex h-full flex-col justify-between text-sm"
	on:submit|preventDefault={async () => {
		updateHandler();
	}}
>
	<h2 class="text-sm font-medium text-gray-900 dark:text-white mb-4">
		{$i18n.t('settings.admin.pipelines.title')}
	</h2>

	<div class="flex-1 min-h-0 overflow-y-auto scrollbar-hover pr-1.5">
		{#if PIPELINES_LIST !== null}
			{#if PIPELINES_LIST.length > 0}
				<input
					id="pipelines-upload-input"
					bind:files={pipelineFiles}
					type="file"
					accept=".py"
					hidden
				/>

				<AdminSettingSection
					title={$i18n.t('settings.admin.pipelines.sections.source.title')}
					first
				>
					<AdminSettingField
						label={$i18n.t('settings.admin.pipelines.pipelineUrl.label')}
						description={$i18n.t('settings.admin.pipelines.pipelineUrl.description')}
						forId="pipelines-url"
					>
						<SettingsSelect
							id="pipelines-url"
							bind:value={selectedPipelinesUrlIdx}
							className="w-full"
							placeholder={$i18n.t('Select a pipeline url')}
							on:change={async () => {
								await tick();
								await setPipelines();
							}}
						>
							<option value="" selected disabled class="bg-gray-100 dark:bg-gray-700"
								>{$i18n.t('Select a pipeline url')}</option
							>

							{#each PIPELINES_LIST as pipelines}
								<option value={pipelines.idx.toString()} class="bg-gray-100 dark:bg-gray-700"
									>{pipelines.url}</option
								>
							{/each}
						</SettingsSelect>
					</AdminSettingField>

					<AdminSettingField
						label={$i18n.t('settings.admin.pipelines.uploadPipeline.label')}
						description={$i18n.t('settings.admin.pipelines.uploadPipeline.description')}
					>
						<div class="flex gap-2">
							<button
								class="h-7 flex-1 rounded-lg border border-dashed border-gray-100/50 bg-transparent px-2 text-left text-xs text-gray-500 transition-colors hover:bg-black/5 hover:text-gray-900 dark:border-white/[0.04] dark:text-gray-500 dark:hover:bg-white/5 dark:hover:text-white"
								type="button"
								on:click={() => {
									document.getElementById('pipelines-upload-input')?.click();
								}}
							>
								{#if pipelineFiles}
									{$i18n.t('{{COUNT}} pipeline(s) selected', { COUNT: pipelineFiles.length })}
								{:else}
									{$i18n.t('settings.admin.pipelines.selectAPyFile.label')}
								{/if}
							</button>

							<button
								class={actionButtonClass}
								on:click={() => {
									uploadPipelineHandler();
								}}
								disabled={uploading}
								type="button"
							>
								{uploading ? $i18n.t('Uploading') : $i18n.t('Upload')}
							</button>
						</div>
					</AdminSettingField>

					<AdminSettingField
						label={$i18n.t('settings.admin.pipelines.githubUrl.label')}
						description={`${$i18n.t('Pipelines are a plugin system with arbitrary code execution.')} ${$i18n.t("Don't fetch random pipelines from sources you don't trust.")}`}
					>
						<div class="flex gap-2">
							<input
								class={inputClass}
								placeholder={$i18n.t('Enter GitHub Raw URL')}
								bind:value={pipelineDownloadUrl}
							/>
							<button
								class={actionButtonClass}
								on:click={() => {
									addPipelineHandler();
								}}
								disabled={downloading}
								type="button"
							>
								{downloading
									? $i18n.t('settings.admin.pipelines.installing.label')
									: $i18n.t('settings.admin.pipelines.install.label')}
							</button>
						</div>
					</AdminSettingField>
				</AdminSettingSection>

				{#if pipelines !== null}
					{#if pipelines.length > 0}
						<AdminSettingSection
							title={$i18n.t('settings.admin.pipelines.sections.pipelines.title')}
						>
							<AdminSettingField
								label={$i18n.t('settings.admin.pipelines.pipeline.label')}
								description={$i18n.t('settings.admin.pipelines.pipeline.description')}
								forId="pipeline"
							>
								<div class="flex gap-2">
									<SettingsSelect
										id="pipeline"
										bind:value={selectedPipelineIdx}
										className="w-full"
										placeholder={$i18n.t('Select a pipeline')}
										on:change={async () => {
											await tick();
											await getValves(selectedPipelineIdx ?? 0);
										}}
									>
										{#each pipelines as pipeline, idx}
											<option value={idx} class="bg-gray-100 dark:bg-gray-700">
												{pipeline.name} ({pipeline.type ?? 'pipe'})
											</option>
										{/each}
									</SettingsSelect>

									<button
										class={actionButtonClass}
										on:click={() => {
											deletePipelineHandler();
										}}
										type="button"
									>
										{$i18n.t('Delete')}
									</button>
								</div>
							</AdminSettingField>
						</AdminSettingSection>

						<AdminSettingSection title={$i18n.t('settings.admin.pipelines.sections.valves.title')}>
							{#if pipelines[selectedPipelineIdx ?? 0]?.valves}
								{#if valves && valves_spec}
									{#each Object.keys(valves_spec.properties) as property}
										<div>
											<AdminSettingRow
												let:labelId
												label={valves_spec.properties[property].title}
												description={valves_spec.properties[property]?.description ?? ''}
											>
												<button
													id={`${labelId}-control`}
													class={actionButtonClass}
													type="button"
													on:click={() => {
														valves[property] = (valves[property] ?? null) === null ? '' : null;
													}}
												>
													{(valves[property] ?? null) === null
														? $i18n.t('None')
														: $i18n.t('Custom')}
												</button>
											</AdminSettingRow>

											{#if (valves[property] ?? null) !== null}
												<div class="mt-1">
													{#if valves_spec.properties[property]?.enum ?? null}
														<SettingsSelect bind:value={valves[property]} className="w-full">
															{#each valves_spec.properties[property].enum as option}
																<option value={option} selected={option === valves[property]}>
																	{option}
																</option>
															{/each}
														</SettingsSelect>
													{:else if (valves_spec.properties[property]?.type ?? null) === 'boolean'}
														<AdminSettingRow
															label={valves[property] ? $i18n.t('Enabled') : $i18n.t('Disabled')}
															labelClassName="text-gray-400 dark:text-gray-600"
															let:labelId
														>
															<Switch bind:state={valves[property]} ariaLabelledbyId={labelId} />
														</AdminSettingRow>
													{:else}
														<input
															class={inputClass}
															type="text"
															placeholder={valves_spec.properties[property].title}
															bind:value={valves[property]}
															autocomplete="off"
															required
														/>
													{/if}
												</div>
											{/if}
										</div>
									{/each}
								{:else}
									<div class="flex justify-center py-2">
										<Spinner className="size-4" />
									</div>
								{/if}
							{:else}
								<div class={mutedMessageClass}>{$i18n.t('No valves')}</div>
							{/if}
						</AdminSettingSection>
					{:else}
						<AdminSettingSection
							title={$i18n.t('settings.admin.pipelines.sections.pipelines.title')}
						>
							<div class={mutedMessageClass}>{$i18n.t('Pipelines Not Detected')}</div>
						</AdminSettingSection>
					{/if}
				{:else}
					<div class="flex justify-center py-4">
						<Spinner className="size-4" />
					</div>
				{/if}
			{:else}
				<AdminSettingSection
					title={$i18n.t('settings.admin.pipelines.sections.source.title')}
					first
				>
					<div class={mutedMessageClass}>{$i18n.t('Pipelines Not Detected')}</div>
				</AdminSettingSection>
			{/if}
		{:else}
			<div class="flex justify-center h-full">
				<div class="my-auto">
					<Spinner className="size-6" />
				</div>
			</div>
		{/if}
	</div>

	{#if PIPELINES_LIST !== null && PIPELINES_LIST.length > 0}
		<div class="flex justify-end pt-6 text-sm font-normal">
			<button
				class="flex h-7 shrink-0 items-center justify-center gap-1.5 rounded-lg bg-gray-900 px-2.5 text-xs font-normal text-white transition hover:bg-black disabled:opacity-60 dark:bg-gray-100 dark:text-gray-900 dark:hover:bg-white"
				type="submit"
			>
				{$i18n.t('Save')}
			</button>
		</div>
	{/if}
</form>
